def align_drift(gi, rowsA, rowsB, bg):
    """Best column drift d so rowsB[j] == rowsA[j-d] (rows paired top-to-top); returns (d, matches)."""
    best, bd = -1, 0
    for d in range(-len(gi[0]), len(gi[0])):
        m = 0
        for k, ib in enumerate(rowsB):
            if k >= len(rowsA):
                break
            ia = rowsA[k]
            for j in range(len(gi[0])):
                v = gi[ib][j]
                jj = j + d
                if 0 <= jj < len(gi[0]) and gi[ia][jj] == v and v != bg:
                    m += 1
        if m > best:
